  // The power section (sleep prevention, issue #325) delegates to the
  // SAME public strict parser CliConfig.fromYaml uses — no mirror to
  // keep in sync, unlike the private-parser sections above.
  'power': (value, _) => parsePowerSection(value),
  // The subagents section (background-subagent heartbeat, issue #383)
  // delegates to the SAME public strict parser CliConfig.fromYaml uses —
  // no mirror to keep in sync.
  'subagents': (value, _) => SubagentsConfig.fromYaml(value),
  // Deep validation (strict prompt names) lives behind cli_config.dart's
  // strict parser; here the section must be a string-valued map.
  'prompts': (value, _) => _validateStringMap(value, 'prompts'),
  // Issue #279: `tui.theme` must be a non-empty string (the theme itself
  // resolves at boot, where the user-theme set is known; unknown names
  // warn and keep the default).
  'tui': (value, label) => _validateTuiSection(value, label),
  // The output section (gh-1198) delegates to the SAME pure strict
  // parser CliConfig.fromYaml uses — no mirror to keep in sync.
  'output': (value, _) => parseOutputSection(value),
  // The self-update policy (issue #1377) mirrors cli_config.dart's strict
  // scalar parser (no import — dart:io); pinned to it by unit test.
  'auto_update': (value, _) => validateAutoUpdateScalar(value),
};

/// The `auto_update` scalar validator (issue #1377): `true`, `false` or
/// the `"notify"` string are legal; anything else throws — the same rule
/// `CliConfig.fromYaml` applies at boot (`autoUpdateModeFromYaml`, which
/// this file cannot import — it uses `dart:io`). Pinned to it by unit
/// test (the `pins against cli_config.dart` group).
void validateAutoUpdateScalar(Object? value) {
  // The yaml package hands back plain scalars (older versions wrap them
  // in YamlScalar) — accept both, like the `_scalarKeys` branch above.
  final scalar = value is YamlScalar ? value.value : value;
  if (scalar is bool || scalar == 'notify' || scalar == null) return;
  throw ConfigException(
    '"auto_update" must be true, false, or "notify", got: $scalar',
  );
}

void _validateTuiSection(Object? node, String label) {
  if (node is! YamlMap) {
    throw ConfigException('$label: tui section must be a map');
  }
  final unknown = [
    for (final key in node.keys)
      if (!{'theme', 'classic', 'showCompactionDetails'}.contains('$key'))
        '$key',
  ];
  if (unknown.isNotEmpty) {
    throw ConfigException(
      '$label: unknown tui key(s): ${unknown.join(', ')} '
      '(known: theme, classic, showCompactionDetails)',
    );
  }
  final theme = node['theme'];
  if (theme != null && '$theme'.trim().isEmpty) {
    throw ConfigException('$label: tui.theme must be a non-empty theme name');
  }
  for (final flag in const ['classic', 'showCompactionDetails']) {
    final value = node[flag];
    if (value != null && value is! bool) {
      throw ConfigException('$label: tui.$flag must be a boolean');
    }
  }
}

void _validateCustomProviders(Object? node) {
  if (node is! YamlList) {
    throw ConfigException('must be a list of provider entries');
  }
  for (final entry in node) {
    CustomProviderEntry.fromYaml(entry);
  }
}

